#!/usr/bin/env bun
/**
 * Fails when a file an agent wrote is over 5,000 tokens, and says how to split
 * it. A token is counted as bytes / 4 (rounded up), so a file of more than
 * 20,000 bytes fails. The limit is strict: a file that was already over it
 * fails too, so whoever next changes one must split it.
 *
 * Files that agents do not write are skipped (`IGNORED_FILES`): lockfiles,
 * changelogs, changesets, generated files, and files git treats as binary.
 *
 * Two modes:
 * - `--staged` (the pre-commit hook, `.githooks/pre-commit`): only the files
 *   staged for commit, sized by their staged content, not the working copy.
 * - default (`bun run lint`, Luca's gates and CI): every file changed on the
 *   branch, meaning changed between the merge-base of `HEAD` and `origin/main`
 *   (or `main`) and the working tree, plus untracked files that git does not
 *   ignore. Deleted files are skipped; files are sized from disk. If neither
 *   `origin/main` nor `main` exists, it prints a one-line note and checks
 *   nothing.
 *
 * Exits 0 and prints nothing when every file is within the limit; exits 1 and
 * prints the offending files and how to split them when one is not.
 *
 * Usage: bun scripts/check-file-size.ts [--staged]
 */
import { lstatSync } from 'node:fs'

/** The most tokens a file may have. */
export const FILE_SIZE_LIMIT_TOKENS = 5000

/** How many leading bytes git looks at to decide a file is binary. */
const BINARY_SNIFF_BYTES = 8000

/** How many git processes run at once when sizing staged files. */
const GIT_CONCURRENCY = 16

/**
 * The files the limit skips because an agent does not write them. Each entry
 * matches a whole path (`path`), a file name in any folder (`name`), or
 * everything under a top-level folder (`directory`).
 */
export const IGNORED_FILES: {
    kind: 'path' | 'name' | 'directory'
    value: string
    reason: string
}[] = [
    {
        kind: 'name',
        value: 'bun.lock',
        reason: 'Bun writes the lockfile; nobody edits it by hand.',
    },
    {
        kind: 'name',
        value: 'CHANGELOG.md',
        reason: 'changesets writes changelogs when a version is cut.',
    },
    {
        kind: 'directory',
        value: '.changeset',
        reason: 'Changesets are short release notes that changesets manages.',
    },
    {
        kind: 'path',
        value: 'packages/engine/src/doctor/v13-files.json',
        reason: 'Generated by packages/engine/scripts/generate-v13-manifest.ts.',
    },
]

/** The kinds of file that get different split instructions. */
export type FileKind = 'source' | 'test' | 'markdown' | 'other'

/** A file over the limit, with its token count. */
export type SizeFailure = { path: string; tokens: number }

/**
 * Counts the tokens in a file of `bytes` bytes: bytes / 4, rounded up.
 *
 * @param bytes - The file's size in bytes.
 * @returns The token count; 20,000 bytes is 5,000 tokens, 20,001 is 5,001.
 */
export const tokenCount = ({ bytes }: { bytes: number }): number =>
    Math.ceil(bytes / 4)

/**
 * Says whether the limit skips a path (see `IGNORED_FILES`).
 *
 * @param path - A path relative to the repo root, with `/` separators.
 * @returns True when an agent does not write the file.
 */
export const isIgnoredPath = ({ path }: { path: string }): boolean => {
    const name = path.slice(path.lastIndexOf('/') + 1)
    return IGNORED_FILES.some(({ kind, value }) => {
        if (kind === 'path') return path === value
        if (kind === 'name') return name === value
        return path.startsWith(`${value}/`)
    })
}

/**
 * Says whether git would treat these bytes as a binary file: a NUL byte in the
 * first 8,000 bytes, which is the rule git itself uses.
 *
 * @param bytes - The start of the file (more than 8,000 bytes is fine).
 * @returns True when the file looks binary.
 */
export const looksBinary = ({ bytes }: { bytes: Uint8Array }): boolean =>
    bytes.subarray(0, BINARY_SNIFF_BYTES).includes(0)

/**
 * Sorts a path into the kind of file that decides which split instructions
 * apply: tests (`*.test.ts`, `*.e2e.test.ts`), source (`.ts`, `.tsx`, `.js`),
 * markdown, or anything else.
 *
 * @param path - A path relative to the repo root.
 * @returns The file's kind.
 */
export const fileKind = ({ path }: { path: string }): FileKind => {
    if (/\.(test|spec)\.(ts|tsx|js)$/.test(path)) return 'test'
    if (/\.(ts|tsx|js)$/.test(path)) return 'source'
    if (/\.(md|mdx)$/.test(path)) return 'markdown'
    return 'other'
}

/**
 * Picks the files over the limit.
 *
 * @param files - Each file's path and size in bytes.
 * @returns The files with more than 5,000 tokens, with their token counts, in
 * the order given.
 */
export const filesOverLimit = ({
    files,
}: {
    files: { path: string; bytes: number }[]
}): SizeFailure[] =>
    files
        .map(({ path, bytes }) => ({ path, tokens: tokenCount({ bytes }) }))
        .filter(({ tokens }) => tokens > FILE_SIZE_LIMIT_TOKENS)

/** How to split each kind of file, one numbered list per kind. */
const SPLIT_INSTRUCTIONS: Record<FileKind, { title: string; steps: string[] }> =
    {
        source: {
            title: 'Source files',
            steps: [
                'Split the file by responsibility into new kebab-case modules beside it, each with one clear job.',
                'Move code, do not rewrite it: no behaviour change.',
                "Keep the original file's exports working: re-export them from it, or update the imports that use them.",
                'Run the type checks and the tests.',
            ],
        },
        test: {
            title: 'Test files',
            steps: [
                'Split the file by describe block into new files named <name>-<topic>.test.ts. Keep the .e2e.test.ts ending for end-to-end files.',
                'If both halves need the same helpers, move them to a small helper module.',
                'Do not change what any test checks; the test count must stay the same.',
                'List each new test file under its feature in docs/feature-map.md (the red check and gates/feature-map-docs.test.ts require it).',
            ],
        },
        markdown: {
            title: 'Markdown files',
            steps: [
                'Split the page into smaller pages by section, for example in a docs/ folder next to it.',
                'Keep a short index in the original that links to each new page.',
                'Fix the links that pointed at the old sections.',
            ],
        },
        other: {
            title: 'Other files',
            steps: ['Split the file by topic into smaller files.'],
        },
    }

/** The last line of every failure message. */
const FOOTER =
    'Tokens are counted as bytes / 4. Lockfiles, changelogs, changesets and generated files are skipped.'

const KIND_ORDER: FileKind[] = ['source', 'test', 'markdown', 'other']

/**
 * Writes the message for a failed check: each offending file with its token
 * count and the limit, then split instructions for each kind of file that
 * failed, then how tokens are counted.
 *
 * @param failures - The files over the limit.
 * @returns The message, or an empty string when nothing failed.
 *
 * @example
 * formatFailure({ failures: [] }) // ''
 * formatFailure({ failures: [{ path: 'src/a.ts', tokens: 6200 }] })
 * // 'These files are over the limit of 5,000 tokens: ...'
 */
export const formatFailure = ({
    failures,
}: {
    failures: SizeFailure[]
}): string => {
    if (failures.length === 0) return ''
    const limit = FILE_SIZE_LIMIT_TOKENS.toLocaleString('en-US')
    const lines = [
        `These files are over the limit of ${limit} tokens:`,
        '',
        ...failures.map(
            ({ path, tokens }) =>
                `  ${path}: ${tokens.toLocaleString('en-US')} tokens (limit ${limit})`
        ),
        '',
        'Split each one before you commit. How:',
    ]
    for (const kind of KIND_ORDER) {
        const paths = failures
            .filter(({ path }) => fileKind({ path }) === kind)
            .map(({ path }) => path)
        if (paths.length === 0) continue
        const { title, steps } = SPLIT_INSTRUCTIONS[kind]
        lines.push('', `${title} (${paths.join(', ')}):`)
        steps.forEach((step, index) => lines.push(`  ${index + 1}. ${step}`))
    }
    lines.push('', FOOTER)
    return lines.join('\n')
}

// ---- The git layer: thin, and the only part that needs a repo. ----

type GitResult = { ok: boolean; stdout: Uint8Array }

/** Runs `git` with `args` in `cwd`; never throws. */
const runGit = async ({
    cwd,
    args,
}: {
    cwd: string
    args: string[]
}): Promise<GitResult> => {
    const child = Bun.spawn(['git', ...args], {
        cwd,
        stdout: 'pipe',
        stderr: 'pipe',
    })
    const [stdout, code] = await Promise.all([
        new Response(child.stdout).arrayBuffer(),
        child.exited,
    ])
    return { ok: code === 0, stdout: new Uint8Array(stdout) }
}

const decode = ({ bytes }: { bytes: Uint8Array }): string =>
    new TextDecoder().decode(bytes)

/** Splits git's `-z` output into its paths. */
const splitNul = ({ bytes }: { bytes: Uint8Array }): string[] =>
    decode({ bytes }).split('\0').filter(Boolean)

/** Maps `items` through `fn`, `GIT_CONCURRENCY` at a time, in order. */
const mapInChunks = async <T, R>({
    items,
    fn,
}: {
    items: T[]
    fn: (item: T) => Promise<R>
}): Promise<R[]> => {
    const results: R[] = []
    for (let start = 0; start < items.length; start += GIT_CONCURRENCY) {
        const chunk = items.slice(start, start + GIT_CONCURRENCY)
        results.push(...(await Promise.all(chunk.map(fn))))
    }
    return results
}

/** Finds the merge-base of `HEAD` and `origin/main`, else `main`. */
const findMergeBase = async ({
    cwd,
}: {
    cwd: string
}): Promise<string | null> => {
    for (const ref of ['origin/main', 'main']) {
        const exists = await runGit({
            cwd,
            args: ['rev-parse', '--verify', '--quiet', `${ref}^{commit}`],
        })
        if (!exists.ok) continue
        const base = await runGit({ cwd, args: ['merge-base', 'HEAD', ref] })
        if (base.ok) return decode({ bytes: base.stdout }).trim()
    }
    return null
}

/** The staged files (added, copied, modified, renamed), and each one's size. */
const stagedFiles = async ({
    cwd,
}: {
    cwd: string
}): Promise<{ path: string; bytes: number }[]> => {
    const listed = await runGit({
        cwd,
        args: ['diff', '--cached', '--name-only', '--diff-filter=ACMR', '-z'],
    })
    const paths = splitNul({ bytes: listed.stdout }).filter(
        (path) => !isIgnoredPath({ path })
    )
    const sized = await mapInChunks({
        items: paths,
        fn: async (path) => {
            const size = await runGit({
                cwd,
                args: ['cat-file', '-s', `:${path}`],
            })
            // A submodule has no blob to size.
            if (!size.ok) return null
            return { path, bytes: Number(decode({ bytes: size.stdout })) }
        },
    })
    return sized.filter((file) => file !== null)
}

/** The branch's changed files (see the file comment), each one's disk size. */
const branchFiles = async ({
    cwd,
    base,
}: {
    cwd: string
    base: string
}): Promise<{ path: string; bytes: number }[]> => {
    const [changed, untracked] = await Promise.all([
        runGit({
            cwd,
            args: ['diff', '--name-only', '--diff-filter=ACMR', '-z', base],
        }),
        runGit({
            cwd,
            args: ['ls-files', '--others', '--exclude-standard', '-z'],
        }),
    ])
    const paths = [
        ...new Set([
            ...splitNul({ bytes: changed.stdout }),
            ...splitNul({ bytes: untracked.stdout }),
        ]),
    ].filter((path) => !isIgnoredPath({ path }))
    return paths.flatMap((path) => {
        try {
            const stat = lstatSync(`${cwd}/${path}`)
            return stat.isFile() ? [{ path, bytes: stat.size }] : []
        } catch {
            return []
        }
    })
}

/** Reads the start of a file, to tell whether git treats it as binary. */
const readHead = async ({
    cwd,
    path,
    staged,
}: {
    cwd: string
    path: string
    staged: boolean
}): Promise<Uint8Array> => {
    if (staged) {
        const blob = await runGit({
            cwd,
            args: ['cat-file', 'blob', `:${path}`],
        })
        return blob.stdout
    }
    const head = Bun.file(`${cwd}/${path}`).slice(0, BINARY_SNIFF_BYTES)
    return new Uint8Array(await head.arrayBuffer())
}

/**
 * Checks the files of the repo that contains `cwd`.
 *
 * @param cwd - Any folder inside the git repo.
 * @param staged - True to check the staged files by their staged content;
 * false to check every file changed on the branch.
 * @returns The files over the limit (binary and ignored files left out), and
 * a note when nothing could be checked.
 */
export const checkRepo = async ({
    cwd,
    staged,
}: {
    cwd: string
    staged: boolean
}): Promise<{ failures: SizeFailure[]; note: string | null }> => {
    const top = await runGit({ cwd, args: ['rev-parse', '--show-toplevel'] })
    if (!top.ok) {
        return {
            failures: [],
            note: 'File size check skipped: not a git repo.',
        }
    }
    const root = decode({ bytes: top.stdout }).trim()
    let files: { path: string; bytes: number }[]
    if (staged) {
        files = await stagedFiles({ cwd: root })
    } else {
        const base = await findMergeBase({ cwd: root })
        if (base === null) {
            return {
                failures: [],
                note: 'File size check skipped: no origin/main or main branch to compare with.',
            }
        }
        files = await branchFiles({ cwd: root, base })
    }
    const over = filesOverLimit({ files })
    const heads = await mapInChunks({
        items: over,
        fn: ({ path }) => readHead({ cwd: root, path, staged }),
    })
    return {
        failures: over.filter((_, index) => {
            const bytes = heads[index]
            return bytes === undefined || !looksBinary({ bytes })
        }),
        note: null,
    }
}

if (import.meta.main) {
    const args = process.argv.slice(2)
    const unknown = args.filter((arg) => arg !== '--staged')
    if (unknown.length > 0) {
        console.error(`Unknown argument: ${unknown.join(' ')}`)
        console.error('Usage: bun scripts/check-file-size.ts [--staged]')
        process.exit(2)
    }
    const { failures, note } = await checkRepo({
        cwd: process.cwd(),
        staged: args.includes('--staged'),
    })
    if (note !== null) console.log(note)
    if (failures.length > 0) {
        console.error(formatFailure({ failures }))
        process.exit(1)
    }
}
